/** The primary tag of an entry ("pt-BR|pt-PT|pt" → "pt-BR"). */
export const primaryTag = (tag: string) => tag.split("|")[0];

const BY_TAG = new Map<string, string>();
for (const l of LANGUAGES) {
  /* the composite key itself must resolve to itself — without this, choosing
     "en|en-US|en-GB" from the list would not round-trip back to the same
     entry, and twelve languages became unselectable */
  BY_TAG.set(l.tag.toLowerCase(), l.tag);
  for (const alias of l.tag.split("|")) BY_TAG.set(alias.toLowerCase(), l.tag);
}

/** Resolves any alias of an entry to the entry's full tag key. */
export function canonicalTag(tag: string | null | undefined): string | null {
  if (!tag) return null;
  const clean = tag.trim().replace(/_/g, "-").toLowerCase();
  if (BY_TAG.has(clean)) return BY_TAG.get(clean)!;
  const base = clean.split("-")[0];
  return BY_TAG.get(base) ?? null;
}

export const LANGUAGE_BY_TAG = new Map(LANGUAGES.map((l) => [l.tag, l]));

/**
 * A row in the language list. Flags are emoji where the platform draws them
 * (Windows does not, so it falls back to a two-letter badge) and the whole
 * page of them is one string, not forty components.
 */
export type LanguageRow = Language & { key: string; value: string };

/** The rows the settings page renders, with a stable key per entry. */
export function languageRows(): LanguageRow[] {
  return LANGUAGES.map((l) => ({
    ...l,
    key: l.tag,
    value: l.tag.split("|")[0],
  }));
}
